    // Prevent directory traversal by checking for '/' or '..' in directory.
    // This is a crucial security measure to prevent writing to arbitrary locations.
    if (strchr(directory, '/') != NULL || strstr(directory, "..") != NULL) {
        return;
    }

    // Construct the full path to the file.
    // Use a buffer that can accommodate the directory, filename, and separator.
    // PATH_MAX is a good choice for maximum path length.
    char filepath[PATH_MAX];
    int written = snprintf(filepath, sizeof(filepath), "%s/%s", directory, filename);

    // Check if snprintf truncated the path or if there was an error.
    if (written < 0 || written >= sizeof(filepath)) {
        return;
    }

    // Check if the directory exists and is writable.
    // This is important to ensure the file is saved in the intended location.
    struct stat st;
    if (stat(directory, &st) == -1) {
        // Directory does not exist or is inaccessible.
        return;
    }
    if (!S_ISDIR(st.st_mode)) {
        // The provided path is not a directory.
        return;
    }
    if (access(directory, W_OK) == -1) {
        // Directory is not writable.
        return;
    }

    // Open the file in write mode.
    FILE *file = fopen(filepath, "w");
    if (file == NULL) {
        // Handle error if file cannot be opened.
        return;
    }

    // Write the content to the file.
    if (fputs(content, file) == EOF) {
        // Handle error if content cannot be written.
        fclose(file);
        return;
    }

    // Close the file.
    if (fclose(file) != 0) {
        // Handle error if closing the file fails.
