        // if closing fails, as it might be in an inconsistent state.
        unlink(filepath);
        return;
    }

    // Set file permissions to be accessible only by the owner (current user).
    // S_IRUSR: Read permission for owner
    // S_IWUSR: Write permission for owner
    if (chmod(filepath, S_IRUSR | S_IWUSR) != 0) {
